<h1>Procurement reports</h1><div class="stats"><div class="stat"><b><?=e($data['requests'])?></b><span>Purchase requests</span></div><div class="stat"><b><?=e($data['orders'])?></b><span>Purchase orders</span></div><div class="stat"><b><?=e($data['vendors'])?></b><span>Vendors</span></div></div><section class="panel"><h2>Purchase order totals by currency</h2><table><tr><th>Currency</th><th>Total</th></tr><?php foreach($data['spend'] as $x):?><tr><td><?=e($x['currency_code'])?></td><td><?=e(number_format((float)$x['total'],2))?></td></tr><?php endforeach?></table><h2>Export data</h2><form method="get" action="<?=e(url('/reports/export'))?>"><select name="type"><?php foreach(['purchase_orders','purchase_requests','vendors','invoices','payments'] as $t):?><option value="<?=e($t)?>"><?=e(ucwords(str_replace('_',' ',$t)))?></option><?php endforeach?></select><select name="format"><option value="csv">CSV</option><option value="xlsx">Excel (.xlsx)</option><option value="pdf">PDF</option></select><button class="btn primary">Download report</button></form></section>
